import re

records = [
    {'id': 'PY-101', 'done': True},
    {'id': 'PY-102', 'done': False}
]

completed_ids = [record['id'] for record in records if record['done']]
for lesson_id in completed_ids:
    valid = re.fullmatch(r'[A-Z]{2}-\d{3}', lesson_id) is not None
    print(f'{lesson_id}: valid={valid}')
